import hashlib,json,os,re,shutil,statistics,subprocess,tempfile,time
from pathlib import Path
os.sched_setaffinity(0,{0})
binaries={'parent':'build/review-j01-adapter/release/mus-solver','candidate':'build/review-j17-lock-final/release/mus-solver'}
data={'method':'Three alternating paired runs, CPU0, one worker, seed7 for new training. Extension uses cloned identical source tables and their stored RNG. Compare every checkpoint and values.txt; ignore training.lock metadata, normalize source directory in extension.txt. No own concurrent builds or tests.','parent_commit':'0373fc1','runs':[],'summary':[]}
def digest(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
data['binary_sha256']={k:digest(v) for k,v in binaries.items()}
data['library_sha256']={k:digest(Path(v).parent/'libmus_solver.a') for k,v in binaries.items()}
data['bot_sha256']={k:digest(Path(v).parent/'mus-bot') for k,v in binaries.items()}
assert len(set(data['library_sha256'].values()))==len(set(data['bot_sha256'].values()))==1
output=Path('/tmp/mus-review-j17-lock-performance.json')
def save():output.write_text(json.dumps(data,indent=2)+'\n')
def hashes(directory):return {p.name:digest(p) for p in sorted(directory.iterdir()) if p.name=='values.txt' or p.name.endswith('.cfr.zst')}
def run(group,version,args,repeat):
 command=[binaries[version],*args]
 with tempfile.TemporaryFile(mode='w+') as log:
  start=time.perf_counter();pid=os.posix_spawn(command[0],command,os.environ,file_actions=[(os.POSIX_SPAWN_DUP2,log.fileno(),1),(os.POSIX_SPAWN_DUP2,log.fileno(),2)])
  _,status,usage=os.wait4(pid,0);elapsed=time.perf_counter()-start;log.seek(0);stdout=log.read()
 if status:raise RuntimeError((command,status,stdout))
 row={'group':group,'version':version,'repeat':repeat,'command':command,'wall_seconds':elapsed,'peak_rss_kib':usage.ru_maxrss,'stdout':stdout}
 data['runs'].append(row);save();print(group,version,repeat,elapsed,usage.ru_maxrss,flush=True);return row
def summary(group):
 rows=[r for r in data['runs'] if r['group']==group];s={'group':group}
 for metric in ['wall_seconds','peak_rss_kib']:
  a=statistics.median(r[metric] for r in rows if r['version']=='parent');b=statistics.median(r[metric] for r in rows if r['version']=='candidate');s[metric]={'parent':a,'candidate':b,'change_percent':100*(b/a-1)}
 data['summary'].append(s);save();print('SUMMARY',json.dumps(s),flush=True)
 if s['wall_seconds']['change_percent']>=20 or s['peak_rss_kib']['change_percent']>=25:raise RuntimeError('Five confirmation pairs required')
with tempfile.TemporaryDirectory(prefix='mus-review-j17-lock-') as tmp:
 root=Path(tmp);reference=None
 for repeat in range(3):
  for version in (['parent','candidate'] if repeat%2==0 else ['candidate','parent']):
   row=run('ordago-public',version,['--format','ordago-public','--iterations','500','--seed','7'],repeat+1)
   counters={k:int(v) for k,v in re.findall(r'(iterations|information_sets|visited_nodes)=([0-9]+)',row['stdout'])}
   if reference is None:reference=counters
   assert counters==reference;row['counters_identical']=True;save()
 summary('ordago-public')
 base_source=root/'base-source'
 subprocess.run([binaries['parent'],'--format','ordago-score','--score','35:35','--iterations','100','--evaluation-samples','10000','--seed','7','--continuation',str(base_source)],check=True,stdout=subprocess.DEVNULL)
 source_hashes=hashes(base_source);data['extension_source_sha256']=source_hashes
 for group in ['score','extension']:
  reference=None;manifest=None
  for repeat in range(3):
   for version in (['parent','candidate'] if repeat%2==0 else ['candidate','parent']):
    directory=root/f'{group}-{version}-{repeat}'
    args=['--format','ordago-score','--score','35:35','--iterations','1000','--evaluation-samples','10000','--continuation',str(directory)]
    if group=='extension':
     source=root/f'source-{version}-{repeat}';shutil.copytree(base_source,source)
     args+=['--extend-continuation',str(source)]
    else:args+=['--seed','7']
    row=run(group,version,args,repeat+1)
    h=hashes(directory);assert len(h)==46
    if reference is None:reference=h
    assert h==reference
    row['files_identical']=True;row['file_sha256']=h
    if group=='extension':
     assert hashes(source)==source_hashes
     assert sorted(p.name for p in source.iterdir())==sorted(source_hashes)
     text=(directory/'extension.txt').read_text().replace(str(source),'<SOURCE>')
     if manifest is None:manifest=text
     assert text==manifest;row['source_preserved']=True;row['normalized_manifest_sha256']=hashlib.sha256(text.encode()).hexdigest()
    save()
  summary(group)
print('ALL_CHECKS_PASSED',flush=True)
